from pathlib import Path
import json,math
from PIL import Image,ImageDraw
p=Path(__file__).resolve().parent
sets={'probe':[dict(stage=1,pelvis=[520,535],withers=[416,184],knee=[465,690],hand=[352,718],ground=966,support=[335,540]),dict(stage=2,pelvis=[1260,540],withers=[1143,185],knee=[1215,690],hand=[1080,727],ground=966,support=[1047,1305])], 'correction':[dict(stage=1,pelvis=[530,575],withers=[415,208],knee=[490,735],hand=[420,754],ground=1007,support=[354,568]),dict(stage=2,pelvis=[1255,580],withers=[1110,225],knee=[1215,735],hand=[1100,787],ground=1007,support=[1077,1300])]}
for attempt,items in sets.items():
 im=Image.open(p/('chelovek-los-r8-proba1.png' if attempt=='probe' else 'chelovek-los-r8-korrekciya.png')).convert('RGB');d=ImageDraw.Draw(im)
 for v in items:
  x,y=v['pelvis'];a,b=v['withers'];v['angle_deg']=round(math.degrees(math.atan2(abs(x-a),abs(y-b))),2)
  v['hand_height_px']=v['ground']-v['hand'][1];v['hand_below_knee_px']=v['hand'][1]-v['knee'][1];v['pelvis_in_support']=v['support'][0]<=x<=v['support'][1]
  v['mid_thigh_y']=(y+v['knee'][1])/2;v['hand_below_mid_thigh_px']=v['hand'][1]-v['mid_thigh_y']
  d.line([(x,b),(x,v['ground'])],fill='blue',width=3);d.line([(x,y),(a,b)],fill='red',width=4)
  d.line([(v['support'][0],v['ground']),(v['support'][1],v['ground'])],fill='green',width=5)
  d.line([(x-160,v['knee'][1]),(x+50,v['knee'][1])],fill='orange',width=3)
  for key in ['pelvis','withers','knee','hand']:
   tx,ty=v[key];d.ellipse((tx-5,ty-5,tx+5,ty+5),fill='red')
  d.text((x-55,y-35),str(v['angle_deg'])+' deg',fill='black',font_size=22)
 im.save(p/('chelovek-los-r8-'+attempt+'-zamery.png'))
(p/'r8-measurements.json').write_text(json.dumps(sets,ensure_ascii=False,indent=2),encoding='utf-8')
prompts=json.loads((p/'r8-prompts.json').read_text(encoding='utf-8-sig'))
with (p/'PROMPTS.md').open('a',encoding='utf-8') as f:
 f.write('\n\n# Лось r8 · 30.10.2026 · редактирование по ролям источников\n\nВстроенный image_gen, режим правки, одна проба и одна корректировка. Вырезки подготовлены `prepare-r8.py`; кроп и равномерное увеличение PIL — подготовка входов, не перерисовка фигур.\n\n## Проба\n\nПорядок приложений:\n\n1. `r8-input-pose.png` — объект правки, профили без органов из `../ChimeraEvolution/Референсы/витрина/человек-лось/тело.png`.\n2. `r8-input-organs.png` — вставки головы/ушей/рогов и копыт из витринного `ступени.png` (r2); тела ст.1/ст.2 не приложены.\n3. `r8-input-upper.png` — анфас ст.1/ст.2 r5: верх, киль, сухие конечности.\n4. `r8-input-balance.png` — нижняя часть r6-proba1, только отношение таза к копытам.\n5. `los-istochniki-r8.png` — главная карта ролей координатора.\n\nВыход: `chelovek-los-r8-proba1.png`.\n\n```text\n'+prompts['probe']+'\n```\n\n## Единственная корректировка\n\nПорядок: проба r8 (объект правки), вырезка позы, органы r2, верх r5, равновесие r6. Все пять изображений подписаны ролью в запросе. Общий лист источников не приложен повторно: лимит инструмента пять входов. Первоначальный вызов с шестью входами отклонён валидатором до генерации; после удаления шестого входа выполнен один корректирующий проход.\n\nВыход: `chelovek-los-r8-korrekciya.png`.\n\n```text\n'+prompts['correction']+'\n```\n')
lines=['\n\n# Лось r8 · 30.10.2026 · порог не пройден\n','Одна проба двух профилей и одна корректировка встроенным **image_gen**. Метод (а): редактирование вырезок профиля `тело.png`, с отдельными входами для органов, верхней поверхности и опоры. **`chelovek-los-r8.png` не собран:** одновременно поза и лосиный верх не получены. Третьего прохода нет. Витрина не менялась, коммит не делался.\n','- [Проба](chelovek-los-r8-proba1.png), [разметка](chelovek-los-r8-probe-zamery.png).\n- [Корректировка](chelovek-los-r8-korrekciya.png), [разметка](chelovek-los-r8-correction-zamery.png).\n- [Запросы и порядок входов](PROMPTS.md), [точные запросы JSON](r8-prompts.json), [замеры JSON](r8-measurements.json), [скрипт замеров](measure-r8.py). Скрипт также дописывает документацию: повторно без необходимости не запускать.\n','## Что откуда\n','Главная опора — [карта источников координатора](los-istochniki-r8.png).\n\n| Источник | Что переносили | Что фактически получилось |\n|---|---|---|\n| Витринное `тело.png`, профили ст.1/ст.2 без органов | Поза, наклон, согнутые опорные ноги и положение таза | Двуногая стойка и опора сохранены по смыслу; точный силуэт и координаты генератор изменил. Наклон ст.2 недостаточен |\n| Витринное `ступени.png`, r2; только вырезки голов и копыт | Морда, уши, рога по ступеням, копыта | Морда, уши и копыта читаются; различие рогов усилено корректировкой, но ст.1 всё ещё с уплощённой роговой основой вместо точного малого ветвистого r2 |\n| Анфас r5 | Плечо-горб в шею, грудь узким килем, сухие руки | Горб и переход в шею читаются; плечевые округлости, утолщения рук и широкая нижняя грудная масса остались |\n| Проба профиля r6; только нижняя вырезка | Таз над копытами | Вертикаль таза внутри диапазона контактов обеих ступеней |\n\nТела ст.1/ст.2 r2 и верх r6 не использовались как образец. Полный лист координатора приложен к пробе с явным разделением ролей. [Подготовка вырезок](prepare-r8.py) воспроизводима; исходники не изменены.\n','## Замеры\n','Оба выхода 1448×1086 px, начало координат слева сверху. Точки вручную по растру: предполагаемый центр тазобедренного сустава, вершина холки, колено и самые низкие кончики кистей. Это оценка изображения, не координаты костей. Угол = atan2(|dx|, |dy|) для таза → холки. Неопределённость примерно ±3–5°, для высоты ориентиров около ±10–15 px. Опора — диапазон контактов двух копыт. Попадание таза в него не доказывает положение общего центра тяжести.\n\nНа разметке: красная ось таза → холки, синяя вертикаль таза, зелёная опора, оранжевый уровень колена.\n\n| Проход | Ст. | Таз → холка, px | Наклон | Таз / опора x | Кончики ниже колена | Высота кончиков над землёй |\n|---|---|---|---|---|---|---|']
for attempt,items in sets.items():
 for v in items:
  lines.append(f"| {'Проба' if attempt=='probe' else 'Корректировка'} | {v['stage']} | {tuple(v['pelvis'])} → {tuple(v['withers'])} | {v['angle_deg']}° | {v['pelvis'][0]} ∈ {v['support']} | {v['hand_below_knee_px']} px | {v['hand_height_px']} px |")
lines += ['\nЦель: ст.1 15–20°, кисти у середины бедра; ст.2 около 35°, кисти чуть выше колена. После корректировки ст.1 около 17° — по наклону попадает. Ст.2 около 22° — не попадает. У ст.1 середина бедра примерно y=655, кончики y=754: ниже цели примерно на 99 px. У ст.2 кончики на 52 px ниже колена. Масштаб фигур между проходами изменился: абсолютные высоты между попытками не сравнивать как изменение длины.\n','## Визуальная приёмка и вывод\n','**Руки не прошли:** на обеих ступенях остаются округлые отдельные плечевые массы и утолщения выше сгиба. Образ тонких сухих ног лося полностью не перенесён. **Грудь не прошла:** верх вытянут, но нижний объём всё ещё округлый и широкий, убедительного узкого киля нет.\n\nСработали разделение размеров рогов, общий лосиный облик головы и холки, двуногая стойка и таз над копытами. Не сработало сохранение позы при поверхностной правке: генератор изменил пропорции и не выдержал даже явно заданные ориентиры корректировки. Это наблюдение по двум выходам, а не доказательство причинного действия отдельных слов.\n\nОбе попытки — материал разбора, не новая цель для моделирования. По органам и конечным ступеням остаётся r2, по мышечному образу — анфас r5, по позе — `тело.png`, по отношению таза к копытам — r6 согласно роли на карте координатора. Условная сборка полного листа из r2/r5 не выполнялась.\n']
with (p/'README.md').open('a',encoding='utf-8') as f:f.write('\n'.join(lines))
print(json.dumps(sets,ensure_ascii=False))
